import { beforeEach, vi } from "vitest";
import { serveStatic, type ServeStaticOptions, type StaticAssetMeta } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("serve static: range requests", (t, { it, expect }) => {
  const body = "0123456789";
  let asset: StaticAssetMeta | undefined;
  let getContents: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    asset = {
      type: "text/plain",
      etag: '"v1"',
      mtime: 1_700_000_000_000,
      size: body.length,
    };
    getContents = vi.fn(() => body);
    const serveStaticOptions: ServeStaticOptions = {
      getMeta: vi.fn((id) => (id.includes("404") ? undefined : asset)),
      getContents,
    };

    t.app.all("/**", (event) => {
      return serveStatic(event, serveStaticOptions);
    });
  });

  it("advertises range support on GET", async () => {
    const res = await t.fetch("/test.txt");

    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe(body);
  });

  it("advertises range support on HEAD", async () => {
    const res = await t.fetch("/test.txt", { method: "HEAD" });

    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
  });

  it("serves a closed range with 206", async () => {
    const res = await t.fetch("/test.txt", { headers: { range: "bytes=2-5" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(res.headers.get("content-length")).toBe("4");
    expect(await res.text()).toBe("2345");
  });

  it("clamps an end past the asset size", async () => {
    const res = await t.fetch("/test.txt", { headers: { range: "bytes=8-99" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 8-9/10");
    expect(res.headers.get("content-length")).toBe("2");
    expect(await res.text()).toBe("89");
  });

  it("serves an open-ended range with 206", async () => {
    const res = await t.fetch("/test.txt", { headers: { range: "bytes=7-" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 7-9/10");
    expect(res.headers.get("content-length")).toBe("3");
    expect(await res.text()).toBe("789");
  });

  it("serves a suffix range with 206", async () => {
    const res = await t.fetch("/test.txt", { headers: { range: "bytes=-3" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 7-9/10");
    expect(res.headers.get("content-length")).toBe("3");
    expect(await res.text()).toBe("789");
  });

  it("serves the whole asset for a suffix longer than the asset", async () => {
    const res = await t.fetch("/test.txt", { headers: { range: "bytes=-99" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-9/10");
    expect(res.headers.get("content-length")).toBe("10");
    expect(await res.text()).toBe(body);
  });

  it.each([
    ["multiple ranges", "bytes=0-1,4-5"],
    ["unknown unit", "itens=0-1"],
    ["reversed bounds", "bytes=5-2"],
    ["empty spec", "bytes="],
    ["non-numeric bounds", "bytes=a-b"],
  ])("ignores a range with %s", async (_, range) => {
    const res = await t.fetch("/test.txt", { headers: { range } });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
    expect(await res.text()).toBe(body);
  });

  it.each([["start past the end", "bytes=20-30"], ["start at the size", "bytes=10-"], ["zero suffix", "bytes=-0"]])(
    "answers 416 for %s",
    async (_, range) => {
      const res = await t.fetch("/test.txt", { headers: { range } });

      expect(res.status).toBe(416);
      expect(res.headers.get("content-range")).toBe("bytes */10");
      expect(res.headers.get("content-length")).toBe("0");
      expect(await res.text()).toBe("");
      expect(getContents).not.toHaveBeenCalled();
    },
  );

  it("sends the range headers on HEAD without reading the content", async () => {
    const res = await t.fetch("/test.txt", {
      method: "HEAD",
      headers: { range: "bytes=2-5" },
    });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
    expect(res.headers.get("content-length")).toBe("4");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  it("answers 416 on HEAD for an unsatisfiable range", async () => {
    const res = await t.fetch("/test.txt", {
      method: "HEAD",
      headers: { range: "bytes=20-30" },
    });

    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */10");
    expect(getContents).not.toHaveBeenCalled();
  });

  it("ignores a range when the asset size is unknown", async () => {
    asset = { type: "text/plain", etag: '"v1"' };
    const res = await t.fetch("/test.txt", { headers: { range: "bytes=0-3" } });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
    expect(await res.text()).toBe(body);
  });

  it("ignores a range when the asset size is zero", async () => {
    asset = { type: "text/plain", etag: '"v1"', size: 0 };
    const res = await t.fetch("/test.txt", { headers: { range: "bytes=0-3" } });

    expect(res.status).toBe(200);
    expect(res.headers.has("content-range")).toBe(false);
  });
});

